#!/usr/bin/env python
"""Convert an RLinf FSDP full_weights.pt (FastWAMPolicy state dict) into a native
FastWAM checkpoint {.pt} = {"mot": ..., "proprio_encoder": ..., step, torch_dtype}
that FastWAM/RLinf eval can load via model.load_checkpoint.

Usage: python convert_ckpt.py <full_weights.pt> <out.pt> [--step N] [--ref <released.pt>]
"""
import argparse
import torch


def _strip(state, prefix):
    return {k[len(prefix):]: v for k, v in state.items() if k.startswith(prefix)}


def _find_subdict(state, marker_suffix):
    """Find the prefix P such that P + marker exists, return P (e.g. 'model.mot.')."""
    cands = set()
    for k in state:
        idx = k.find(marker_suffix)
        if idx != -1:
            cands.add(k[:idx])
    return cands


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("full_weights")
    ap.add_argument("out")
    ap.add_argument("--step", type=int, default=None)
    ap.add_argument("--ref", default="/workspace/fastwam_ckpt/libero_uncond_2cam224.pt")
    args = ap.parse_args()

    full = torch.load(args.full_weights, map_location="cpu", weights_only=False)
    # full_weights.pt is a plain state_dict (OrderedDict of tensors)
    if not isinstance(full, dict):
        raise SystemExit(f"Unexpected full_weights type: {type(full)}")
    print(f"[convert] full_weights: {len(full)} keys")
    sample = list(full.keys())[:3]
    print(f"[convert] sample keys: {sample}")

    # Locate mot via the well-known 'mixtures.video.patch_embedding.weight' marker.
    marker = "mot.mixtures."
    prefixes = _find_subdict(full, marker)
    # prefer a prefix ending exactly in 'model.' before 'mot' (i.e. policy.model.mot)
    mot_prefix = None
    for p in sorted(prefixes, key=len):
        mot_prefix = p + "mot."
        break
    if mot_prefix is None:
        # fall back: maybe keys already start with 'mixtures.'
        if any(k.startswith("mixtures.") for k in full):
            mot = {k: v for k, v in full.items() if k.startswith("mixtures.")}
            mot_prefix = "(none, raw mixtures.)"
        else:
            raise SystemExit("Could not locate MoT keys (no '*mot.mixtures.*' or 'mixtures.*').")
    else:
        mot = _strip(full, mot_prefix)
        # keep only mixtures.* (drop any non-mixtures leakage)
        mot = {k: v for k, v in mot.items() if k.startswith("mixtures.")}
    print(f"[convert] mot prefix='{mot_prefix}' -> {len(mot)} keys")

    # proprio_encoder
    pe_prefixes = _find_subdict(full, "proprio_encoder.weight")
    pe = {}
    if pe_prefixes:
        pe_prefix = sorted(pe_prefixes, key=len)[0] + "proprio_encoder."
        pe = _strip(full, pe_prefix)
        pe = {k: v for k, v in pe.items() if k in ("weight", "bias")}
        print(f"[convert] proprio_encoder prefix='{pe_prefix}' -> {list(pe.keys())}")
    else:
        print("[convert] WARNING: no proprio_encoder found")

    payload = {"mot": mot, "step": args.step, "torch_dtype": "torch.bfloat16"}
    if pe:
        payload["proprio_encoder"] = pe

    # Validate against the released reference key set.
    if args.ref:
        ref = torch.load(args.ref, map_location="cpu", weights_only=False)
        ref_mot = set(ref["mot"].keys())
        got_mot = set(mot.keys())
        missing = ref_mot - got_mot
        extra = got_mot - ref_mot
        print(f"[validate] ref mot keys={len(ref_mot)} got={len(got_mot)} "
              f"missing={len(missing)} extra={len(extra)}")
        if missing:
            print("  MISSING sample:", list(missing)[:5])
        if extra:
            print("  EXTRA sample:", list(extra)[:5])
        # shape check on a few keys
        bad_shapes = 0
        for k in list(ref_mot & got_mot)[:50]:
            if ref["mot"][k].shape != mot[k].shape:
                bad_shapes += 1
        print(f"[validate] shape mismatches in first 50 shared keys: {bad_shapes}")
        if "proprio_encoder" in ref:
            print("[validate] ref proprio_encoder keys:", list(ref["proprio_encoder"].keys()))
        ok = (not missing) and (not extra) and bad_shapes == 0
        print(f"[validate] KEY-SET MATCH: {ok}")

    torch.save(payload, args.out)
    print(f"[convert] wrote {args.out}")


if __name__ == "__main__":
    main()

